presetParts.perFrame:
dec_med = exp(-10/fps);
dec_slow = exp(-3/fps);

beat = bass+ mid; 
avg = avg*dec_slow + beat*(1-dec_slow);
is_beat = above(beat, .2+avg+peak) * above (time, t0+.2);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_med;
index = (index + is_beat) %8;
index2 = (index2 + is_beat*bnot(index))%4;
index3 = (index3 + is_beat*bnot(index)*bnot(index2))%3;


q20 = avg;
q21 = beat;
q22 = peak;
q23 = index;
q24 = is_beat;
q26 = bass + mid + treb;
ava = ava*dec_slow + q26*(1-dec_slow);



//k1 =  is_beat*bnot(index)*bnot(index2);

k1 =  is_beat*equal(index%2,0);
p1 =  k1*(p1+1) + (1-k1)*p1;
p2 = dec_med * p2+ (1-dec_med)*p1;
rott = p2 * 3.1416/4;
q1 = cos(rott);
q2 = sin(rott);

q27 = 8-index;
q28 = .5 + sin(time/7)/10;

mov = is_beat*(q26) + (1-is_beat)*mov;
mov_ = dec_med*mov_ + (1-dec_med)*mov;

movez = movez + .1/fps*mov_;
q30 = movez;
//**************************


movex = movex + .2/fps*sin(rott);
movey = movey + .2/fps*cos(rott);

q18 = movex; q19 = movey;
q16 = (q27+2)/4;
q15 = q27/3 + time/8;

